    "model": "glm-5.3-flashx",
    "messages": [
        {
            "role": "user",
            "content": "你是谁"
        }
    ],
    "stream": true,
    "stream_options": {
        "include_usage": true
    },
    "enable_thinking": true,
    "reasoning_effort": "max"
}'","sectionTitle":"","name":"curl"}]}}

